source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    interior = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 0 and (r,c) not in outside}
    if not interior:
        return [row[:] for row in grid]

    # Identify 1-components that border a bounded zero region.
    ones = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    active = set()
    for r,c in interior:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(r+dr,c+dc)
            if p in ones:
                active.add(p)
    seen=set(); active_components=[]
    for start in active:
        if start in seen: continue
        comp=set([start]); seen.add(start); q=deque([start])
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if p in ones and p not in seen:
                    seen.add(p); comp.add(p); q.append(p)
        active_components.append(comp)

    out=[row[:] for row in grid]
    # Paint the inner edge of each bounded region.
    for r,c in interior:
        if any((r+dr,c+dc) in ones for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
            out[r][c]=3
    # Add an 8-neighbour outer rim around the corresponding 1-components.
    for comp in active_components:
        for r,c in comp:
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) in outside:
                        out[nr][nc]=2
    return out
